"""Implement against the original library and native root-session core, not mocks."""
from typing import Any, Protocol
from .rotation import Snapshot, Summary, Agent, Switch

class LibraryPort(Protocol):
    connected: bool
    def write(self, kind: str, idempotency_key: str, payload: str) -> str: ...
    def read(self, artifact_id: str) -> str: ...

class SummaryPort(Protocol):
    def build(self, snapshot: Snapshot, archive_id: str, idempotency_key: str) -> Summary: ...

class SessionPort(Protocol):
    capabilities: frozenset[str]
    def acquire_safe_point(self, snapshot: Snapshot, operation_id: str) -> Any | None: ...
    def is_current(self, lease: Any, snapshot: Snapshot) -> bool: ...
    def create_dormant(self, handoff_payload: str, idempotency_key: str) -> Agent: ...
    def lookup_created(self, idempotency_key: str) -> Agent | None: ...
    def read_agent(self, agent_id: str) -> Agent: ...
    def commit_rotation(self, lease: Any, snapshot: Snapshot, new_agent: str, operation_id: str) -> Switch: ...
    def lookup_switch(self, operation_id: str) -> Switch | None: ...
    def current_agent(self, conversation_id: str) -> str: ...
    def release_safe_point(self, lease: Any, operation_id: str) -> None: ...
    def release_operation_fence(self, operation_id: str) -> None: ...
    def contain_uncertain(self, conversation_id: str, operation_id: str) -> None: ...
    def clear_uncertain(self, conversation_id: str, operation_id: str) -> None: ...
